<script setup lang="ts">
import { Search, Users, X, UserPlus, Settings, Copy, ShieldCheck } from '@lucide/vue';
import { requestKey } from '~/shared/request-key';
const props=defineProps<{profile:any}>(), emit=defineEmits<{changed:[message:string]}>(), session=useB2BSession();
const query=ref(''),role=ref(''),data=ref<any>(null),loading=ref(true),busy=ref(false),error=ref(''),notice=ref(''),localLink=ref('');
const edit=ref<'invite'|'member'|'transfer'|null>(null),selected=ref<any>(null),baseline=ref('');
const form=reactive({email:'',role:'EMPLOYEE',canOrder:false,canSeeFinance:false,isActive:true,targetMemberId:'',currentPassword:'',confirmed:false,key:''});
const roles:Record<string,string>={OWNER:'Владелец',EMPLOYEE:'Сотрудник',BUYER:'Закупщик',ACCOUNTANT:'Бухгалтер'};
const members=computed(()=>data.value?.members||props.profile.members||[]),canManage=computed(()=>data.value?.canManage===true);
const name=(item:any)=>[item.user.firstName,item.user.lastName].filter(Boolean).join(' ')||item.user.email||'Сотрудник';
const filtered=computed(()=>members.value.filter((item:any)=>(!role.value||item.role===role.value)&&`${name(item)} ${item.user.email||''} ${item.user.phone||''}`.toLocaleLowerCase('ru-RU').includes(query.value.trim().toLocaleLowerCase('ru-RU'))));
const candidates=computed(()=>members.value.filter((item:any)=>item.isActive&&item.id!==data.value?.currentMemberId));
const dirty=computed(()=>Boolean(edit.value)&&JSON.stringify(form)!==baseline.value);
function access(item:any){return [(['OWNER','EMPLOYEE'].includes(item.role)?'Запись и клиенты':null),item.canOrder?'Закупки':null,item.canSeeFinance?'Финансы':null,item.role==='OWNER'?'Настройки и команда':null].filter(Boolean);}
function message(e:any){return Array.isArray(e?.data?.message)?e.data.message.join('. '):e?.data?.message||e?.message||'Действие не выполнено. Повторите попытку.';}
async function load(){loading.value=true;error.value='';try{data.value=await session.request('/b2b/team');}catch(e){error.value=message(e);}finally{loading.value=false;}}
function open(mode:'invite'|'member'|'transfer',item:any=null){if(busy.value)return;selected.value=item;Object.assign(form,{email:'',role:item?.role==='OWNER'?'EMPLOYEE':item?.role||'EMPLOYEE',canOrder:item?.canOrder||false,canSeeFinance:item?.canSeeFinance||false,isActive:item?.isActive??true,targetMemberId:'',currentPassword:'',confirmed:false,key:requestKey()});edit.value=mode;baseline.value=JSON.stringify(form);error.value='';}
function close(){if(busy.value||dirty.value&&!window.confirm('Изменения команды не сохранены. Закрыть форму?'))return false;edit.value=null;form.currentPassword='';return true;}
const {panel,keyboard}=useCatalogDialog(computed(()=>Boolean(edit.value)),close);
async function save(){if(busy.value)return;const action=edit.value;busy.value=true;error.value='';notice.value='';try{
  if(edit.value==='invite'){const value:any=await session.request('/b2b/team/invitations',{method:'POST',body:{requestKey:form.key,email:form.email.trim(),role:form.role,canOrder:form.canOrder,canSeeFinance:form.canSeeFinance}});localLink.value=value.localLink||'';notice.value=value.reused?'Приглашение уже создано.':'Приглашение создано. Письмо добавлено в очередь отправки.';}
  else if(edit.value==='member'){await session.request(`/b2b/team/members/${selected.value.id}`,{method:'PATCH',body:{version:selected.value.version,role:form.role,canOrder:form.canOrder,canSeeFinance:form.canSeeFinance,isActive:form.isActive}});notice.value='Доступ сотрудника обновлён. Записи и история сохранены.';}
  else {if(!form.confirmed)throw new Error('Подтвердите передачу управления');const target=members.value.find((item:any)=>item.id===form.targetMemberId),owner=members.value.find((item:any)=>item.id===data.value.currentMemberId);await session.request('/b2b/team/transfer-ownership',{method:'POST',body:{targetMemberId:form.targetMemberId,ownerVersion:owner.version,targetVersion:target.version,currentPassword:form.currentPassword}});notice.value='Управление передано. Ваш доступ к финансам и закупкам отключён.';await session.loadOrganizations(true);}
  edit.value=null;form.currentPassword='';await load();if(action!=='invite')emit('changed',notice.value);
 }catch(e){error.value=message(e);}finally{busy.value=false;}}
async function revoke(item:any){if(busy.value||!window.confirm('Отозвать это приглашение?'))return;busy.value=true;error.value='';try{await session.request(`/b2b/team/invitations/${item.id}/revoke`,{method:'POST',body:{version:item.version}});localLink.value='';notice.value='Приглашение отозвано';await load();}catch(e){error.value=message(e);}finally{busy.value=false;}}
async function copy(){try{await navigator.clipboard.writeText(localLink.value);notice.value='Ссылка скопирована';}catch{error.value='Выделите и скопируйте ссылку вручную';}}
function leave(){return !busy.value&&(!dirty.value||window.confirm('Изменения команды не сохранены. Покинуть раздел?'));}
onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave);onMounted(load);
</script>
<template>
 <section class="salon-services-panel salon-team-panel" aria-label="Команда организации">
  <header class="salon-overview-heading"><div><h2>Команда</h2><p>Доступ к записям, закупкам и финансам для каждого сотрудника.</p></div><button v-if="canManage" type="button" class="primary" :disabled="busy" @click="open('invite')"><UserPlus :size="18"/>Пригласить сотрудника</button></header>
  <p v-if="loading" role="status">Загружаем команду…</p><p v-if="error&&!edit" class="salon-settings-error" role="alert">{{error}} <button type="button" @click="load">Обновить команду</button></p><p v-if="notice" role="status">{{notice}}</p>
  <div v-if="localLink" class="salon-settings-notes"><strong>Локальный режим: отправка писем отключена</strong><p>Передайте ссылку адресату приглашения. Она показывается один раз и действует 7 дней.</p><label>Ссылка приглашения<input :value="localLink" readonly @focus="($event.target as HTMLInputElement).select()"/></label><button type="button" @click="copy"><Copy :size="16"/>Скопировать ссылку</button></div>
  <div class="salon-services-filters salon-team-filters"><label class="salon-services-search"><Search :size="18"/><input v-model="query" type="search" placeholder="Имя, email или телефон" aria-label="Поиск сотрудников"/></label><select v-model="role" aria-label="Роль сотрудника"><option value="">Все роли</option><option v-for="(label,value) in roles" :key="value" :value="value">{{label}}</option></select></div>
  <table v-if="filtered.length" class="salon-services-table salon-team-table" aria-label="Список сотрудников"><thead><tr><th scope="col">Сотрудник</th><th scope="col">Контакты</th><th scope="col">Роль</th><th scope="col">Доступы</th><th v-if="canManage" scope="col">Действия</th></tr></thead><tbody><tr v-for="item in filtered" :key="item.id" class="salon-service-row salon-team-row"><th scope="row" class="salon-service-info"><div><span class="salon-person-avatar" aria-hidden="true">{{name(item).slice(0,1).toUpperCase()}}</span><strong>{{name(item)}}</strong></div><small v-if="item.isActive===false">Доступ отключён</small></th><td class="salon-person-contacts" data-label="Контакты"><a v-if="item.user.email" :href="`mailto:${item.user.email}`">{{item.user.email}}</a><a v-if="item.user.phone" :href="`tel:${item.user.phone.replace(/[^+\d]/g,'')}`">{{item.user.phone}}</a></td><td class="salon-team-role" data-label="Роль"><span class="salon-service-status" :class="{'is-owner':item.role==='OWNER'}">{{roles[item.role]}}</span></td><td class="salon-team-access" data-label="Доступы"><div class="salon-client-tags"><small v-for="label in access(item)" :key="label">{{label}}</small><small v-if="!access(item).length">Без расширенных доступов</small></div></td><td v-if="canManage" data-label="Действия"><button v-if="item.id!==data.currentMemberId" type="button" :disabled="busy" :aria-label="`Изменить доступ ${name(item)}`" @click="open('member',item)"><Settings :size="16"/>Доступ</button><small v-else>Вы</small></td></tr></tbody></table>
  <div v-else-if="!loading" class="salon-services-empty"><Users :size="24"/><h3>Сотрудники не найдены</h3><p>Измените поиск или пригласите сотрудника.</p></div>
  <section v-if="canManage&&data?.invitations?.length" class="business-team-invitations"><h3>Приглашения</h3><article v-for="item in data.invitations" :key="item.id"><div><strong>{{item.email}}</strong><small>{{roles[item.role]}} · {{({PENDING:'Ожидает ответа',ACCEPTED:'Принято',REVOKED:'Отозвано',EXPIRED:'Срок истёк'} as Record<string,string>)[item.status]}}</small></div><button v-if="item.status==='PENDING'" type="button" :disabled="busy" :aria-label="`Отозвать приглашение ${item.email}`" @click="revoke(item)">Отозвать</button></article></section>
  <footer class="salon-services-total"><small>Сотрудников: {{filtered.length}} из {{members.length}}</small><button v-if="canManage&&candidates.length" type="button" :disabled="busy" @click="open('transfer')"><ShieldCheck :size="16"/>Передать управление</button></footer>
 </section>
 <Teleport to="body"><div v-if="edit" class="business-team-backdrop" @click.self="close"><section ref="panel" class="business-team-dialog admin-dialog" role="dialog" aria-modal="true" aria-labelledby="business-team-title" tabindex="-1" @keydown="keyboard"><header><h2 id="business-team-title">{{edit==='invite'?'Пригласить сотрудника':edit==='transfer'?'Передать управление':`Доступ: ${name(selected)}`}}</h2><button type="button" :disabled="busy" aria-label="Закрыть форму команды" @click="close"><X :size="20"/></button></header>
  <form @submit.prevent="save"><template v-if="edit!=='transfer'"><label v-if="edit==='invite'">Email сотрудника<input v-model.trim="form.email" type="email" maxlength="254" required :disabled="busy"/></label><label>Роль<select v-model="form.role" aria-label="Роль" :disabled="busy"><option value="EMPLOYEE">Сотрудник — записи и клиенты салона</option><option value="BUYER">Закупщик — каталог и заказы</option><option value="ACCOUNTANT">Бухгалтер — заказы и документы</option></select></label><label class="business-team-check"><input v-model="form.canOrder" type="checkbox" :disabled="busy"/>Разрешить оформление закупок</label><label class="business-team-check"><input v-model="form.canSeeFinance" type="checkbox" :disabled="busy"/>Разрешить просмотр финансов</label><label v-if="edit==='member'" class="business-team-check"><input v-model="form.isActive" type="checkbox" :disabled="busy"/>Доступ сотрудника включён</label><p>Доступ к настройкам и управлению командой остаётся у владельца. Отключение доступа сохраняет записи клиентов и историю.</p></template>
   <template v-else><p>Новый владелец получит настройки компании, команду, закупки и финансы. Вы останетесь сотрудником салона; доступ к закупкам и финансам будет отключён.</p><label>Новый владелец<select v-model="form.targetMemberId" aria-label="Новый владелец" required :disabled="busy"><option value="" disabled>Выберите сотрудника</option><option v-for="item in candidates" :key="item.id" :value="item.id">{{name(item)}}</option></select></label><label>Ваш текущий пароль<input v-model="form.currentPassword" type="password" autocomplete="current-password" required maxlength="128" :disabled="busy"/></label><label class="business-team-check"><input v-model="form.confirmed" type="checkbox" required :disabled="busy"/>Подтверждаю передачу управления и изменение моего доступа</label></template>
   <p v-if="error" role="alert" class="salon-settings-error">{{error}}</p><footer><button type="button" :disabled="busy" @click="close">Отмена</button><button type="submit" class="primary" :disabled="busy">{{busy?'Сохраняем…':edit==='invite'?'Отправить приглашение':edit==='transfer'?'Передать управление':'Сохранить доступ'}}</button></footer>
  </form></section></div></Teleport>
</template>
